questions.starter:
const payments = [1500, 800, 0, 5000, 12000, 3000];
// Note: 0 is a failed payment — skip it
// Stop (break) at the first payment > 10000

// Write your for...of loop here

questions.solution:
const payments = [1500, 800, 0, 5000, 12000, 3000];

for (const amount of payments) {
  if (amount === 0) {
    continue;
  }
  if (amount > 10000) {
    console.log('Large payment found: ₦' + amount + ' — stopping');
    break;
  }
  console.log('Processed: ₦' + amount);
}
